// Narration: plays the saved ElevenLabs file (/audio/<id>.mp3) if it exists; otherwise /api/tts generates it once and saves it.
// Falls back to the browser's voice when neither is available.
let tts=null,ttsOk=null;const ttsIds=new Map();
const ttsUrl=t=>'/api/tts?text='+encodeURIComponent(t);
async function ttsId(t){if(ttsIds.has(t))return ttsIds.get(t);let id=null;try{const b=await crypto.subtle.digest('SHA-1',new TextEncoder().encode(t));id=[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('').slice(0,16)}catch(e){}ttsIds.set(t,id);return id}
function stopAudio(){if(tts){const a=tts;tts=null;try{a.pause();a.removeAttribute('src');a.load()}catch(e){}}}
function speak(t,g){spoken=false;stopAudio();try{window.speechSynthesis&&speechSynthesis.cancel()}catch(e){}
  setTimeout(()=>{if(g===gen)spoken=true},t.length*110+9000);
  ttsId(t).then(id=>{if(g!==gen)return;
    const srcs=[id&&'/audio/'+id+'.mp3',ttsOk===false?null:ttsUrl(t)].filter(Boolean);
    const tryAt=i=>{if(g!==gen)return;if(i>=srcs.length){tts=null;speakBrowser(t,g);return}
      const a=new Audio(srcs[i]);tts=a;a.playbackRate=speed;a.preservesPitch=true;
      const fail=()=>{if(tts===a)tryAt(i+1)};a.onended=()=>{if(g===gen)spoken=true};a.onerror=fail;a.play().catch(fail)};
    tryAt(0)});
  const nx=ep&&ep.scenes[cur+1];
  if(nx&&playing)ttsId(nx.cap).then(id=>fetch(id?'/audio/'+id+'.mp3':ttsUrl(nx.cap),{method:id?'HEAD':'GET'}).then(r=>{if(!r.ok&&ttsOk!==false)return fetch(ttsUrl(nx.cap))})).catch(()=>{})}
function speakBrowser(t,g){spoken=false;try{const ss=window.speechSynthesis;if(!ss){spoken=true;return}ss.cancel();const u=new SpeechSynthesisUtterance(t);u.rate=speed;
  const vs=ss.getVoices();const v=vs.find(v=>/en-IN/i.test(v.lang))||vs.find(v=>/^en/i.test(v.lang));if(v)u.voice=v;u.onend=()=>{if(g===gen)spoken=true};u.onerror=()=>{spoken=true};ss.speak(u);
  setTimeout(()=>{if(g===gen)spoken=true},t.length*110+4000)}catch(e){spoken=true}}
function play(){playing=true;lbl($('bplay'),'pause','Pause');$('player').classList.add('playing');const keep=elapsed;show(cur);if(keep&&keep<dur){elapsed=keep;startT=performance.now()-keep/speed}}
